SELECT DISTINCT DATE(TRUNC_TIMESTAMP("DATES_ARTICLE"."PUB_DATETIME", 'DD')) AS "DATEFIELD" FROM "DATES_ARTICLE" WHERE "DATES_ARTICLE"."PUB_DATETIME" IS NOT NULL ORDER BY 1 ASC;
SELECT DISTINCT DATE(TRUNC_TIMESTAMP("DATES_ARTICLE"."PUB_DATE", 'DD')) AS "DATEFIELD" FROM "DATES_CATEGORY" LEFT OUTER JOIN "DATES_ARTICLE_CATEGORIES" ON ("DATES_CATEGORY"."ID" = "DATES_ARTICLE_CATEGORIES"."CATEGORY_ID") LEFT OUTER JOIN "DATES_ARTICLE" ON ("DATES_ARTICLE_CATEGORIES"."ARTICLE_ID" = "DATES_ARTICLE"."ID") WHERE "DATES_ARTICLE"."PUB_DATE" IS NOT NULL ORDER BY 1 ASC;
SELECT DISTINCT DATE(TRUNC_TIMESTAMP("DATES_ARTICLE"."PUB_DATE", 'DD')) AS "DATEFIELD" FROM "DATES_COMMENT" INNER JOIN "DATES_ARTICLE" ON ("DATES_COMMENT"."ARTICLE_ID" = "DATES_ARTICLE"."ID") WHERE "DATES_ARTICLE"."PUB_DATE" IS NOT NULL ORDER BY 1 ASC;
SELECT DISTINCT DATE(TRUNC_TIMESTAMP("DATES_ARTICLE"."PUB_DATE", 'IW')) AS "DATEFIELD" FROM "DATES_COMMENT" INNER JOIN "DATES_ARTICLE" ON ("DATES_COMMENT"."ARTICLE_ID" = "DATES_ARTICLE"."ID") WHERE "DATES_ARTICLE"."PUB_DATE" IS NOT NULL ORDER BY 1 ASC;
SELECT DISTINCT DATE(TRUNC_TIMESTAMP("DATES_ARTICLE"."PUB_DATE", 'MONTH')) AS "DATEFIELD" FROM "DATES_COMMENT" INNER JOIN "DATES_ARTICLE" ON ("DATES_COMMENT"."ARTICLE_ID" = "DATES_ARTICLE"."ID") WHERE "DATES_ARTICLE"."PUB_DATE" IS NOT NULL ORDER BY 1 ASC;
SELECT DISTINCT DATE(TRUNC_TIMESTAMP("DATES_ARTICLE"."PUB_DATE", 'YEAR')) AS "DATEFIELD" FROM "DATES_COMMENT" INNER JOIN "DATES_ARTICLE" ON ("DATES_COMMENT"."ARTICLE_ID" = "DATES_ARTICLE"."ID") WHERE "DATES_ARTICLE"."PUB_DATE" IS NOT NULL ORDER BY 1 ASC;
SELECT DISTINCT DATE(TRUNC_TIMESTAMP("DATES_COMMENT"."APPROVAL_DATE", 'DD')) AS "DATEFIELD" FROM "DATES_ARTICLE" LEFT OUTER JOIN "DATES_COMMENT" ON ("DATES_ARTICLE"."ID" = "DATES_COMMENT"."ARTICLE_ID") WHERE "DATES_COMMENT"."APPROVAL_DATE" IS NOT NULL ORDER BY 1 ASC;
SELECT DISTINCT DATE(TRUNC_TIMESTAMP("DATES_COMMENT"."PUB_DATE", 'DD')) AS "DATEFIELD" FROM "DATES_ARTICLE" LEFT OUTER JOIN "DATES_COMMENT" ON ("DATES_ARTICLE"."ID" = "DATES_COMMENT"."ARTICLE_ID") WHERE "DATES_COMMENT"."PUB_DATE" IS NOT NULL ORDER BY 1 ASC;
